function drawGroups(pos,out,ri,prefix,w){
  const groups=new Map();pos.forEach(p=>{if(p.e.tuplet){const id=p.e.tuplet.id;if(!groups.has(id))groups.set(id,[]);groups.get(id).push(p);}});
  groups.forEach(g=>{const t=g[0].e.tuplet,x1=g[0].x-5,x2=g.at(-1).x+18,y=Math.min(...g.map(p=>Math.min(p.top-12,p.y-49))),mid=(x1+x2)/2;out.push(`<g ${symbolAttrs('tuplet',g[0].mi,g[0].e.id)}><title>${t.count} 个音均分 ${t.total} 个四分拍</title><path d="M ${x1} ${y+5} V ${y} H ${mid-10} M ${mid+10} ${y} H ${x2} V ${y+5}" fill="none" stroke="#454c46"/><path class="symbol-hit" d="M ${x1} ${y} H ${x2}"/><text x="${mid}" y="${y+4}" text-anchor="middle" font-size="12" font-style="italic">${t.count}</text><text x="${mid}" y="${y-11}" text-anchor="middle" font-size="9" fill="#8a9386">共 ${M.fmt(t.total)} 拍</text></g>`);});
  for(let i=0;i<pos.length;i++){const p=pos[i];if(p.e.triplet&&!p.e.tuplet){let end=i;while(end+1<pos.length&&pos[end+1].e.triplet&&end-i<2)end++;out.push(`<text x="${(p.x+pos[end].x)/2}" y="${Math.min(...pos.slice(i,end+1).map(p=>p.y-50))}" font-size="12">3</text>`);i=end;}}
  for(let i=0;i<pos.length;i++){const p=pos[i];if(!p.e.ottava)continue;let end=i;while(end+1<pos.length&&pos[end+1].e.ottava===p.e.ottava)end++;const label={1:'8va','-1':'8vb',2:'15ma','-2':'15mb'}[p.e.ottava],y=p.e.ottava>0?p.offset+15:p.lyricY+21,x1=p.x-9,x2=pos[end].x+23;out.push(`<g ${symbolAttrs('ottava',p.mi,p.e.id)}><text class="octave-label" x="${x1}" y="${y}" font-size="12" font-style="italic">${label}</text><path class="octave-line" d="M ${x1+32} ${y-4} H ${x2} V ${y+(p.e.ottava>0?3:-11)}" fill="none" stroke="#65725f" stroke-dasharray="4 3"/><path class="symbol-hit" d="M ${x1} ${y-4} H ${x2}"/></g>`);i=end;}
  const slurs=new Map();pos.filter(p=>p.e.slur).forEach(p=>{if(!slurs.has(p.e.slur))slurs.set(p.e.slur,[]);slurs.get(p.e.slur).push(p);});slurs.forEach(g=>{const a=g[0],b=g.at(-1),all=score.measures.flatMap(m=>M.events(score,m,a.voice)).filter(e=>e.slur===a.e.slur),start=all[0].id===a.e.id,end=all.at(-1).id===b.e.id,x1=start?a.x+10:prefix,x2=end?b.x+2:w-20,y1=a.y+23,y2=b.y+23;if(x2>x1){const d=`M ${x1} ${y1} Q ${(x1+x2)/2} ${Math.max(y1,y2)+20} ${x2} ${y2}`;out.push(`<g ${symbolAttrs('slur',a.mi,a.e.id)}><path d="${d}" fill="none" stroke="#465c4b" stroke-width="1.4"/><path class="symbol-hit" d="${d}"/></g>`);}else out.push(`<g ${symbolAttrs('slur',a.mi,a.e.id)}><text x="${a.x+8}" y="${a.y+30}" font-size="16">⌒</text></g>`);});
}

function drawArticulationSymbol(kind,x,y){let mark='';if(kind==='staccato')mark=`<circle cx="${x+7}" cy="${y-4}" r="2" fill="#333"/>`;if(kind==='staccatissimo')mark=`<path d="M ${x+3} ${y-9} L ${x+11} ${y-9} L ${x+7} ${y} Z" fill="#333"/>`;if(kind==='accent')mark=`<path d="M ${x+1} ${y-8} L ${x+14} ${y-4} L ${x+1} ${y}" fill="none" stroke="#333"/>`;if(kind==='marcato')mark=`<path d="M ${x+1} ${y} L ${x+7} ${y-9} L ${x+14} ${y}" fill="none" stroke="#333"/>`;if(kind==='tenuto'||kind==='portato')mark=line(x,y-4,x+14,y-4,'staff-line','stroke-width="2"');if(kind==='portato')mark+=`<circle cx="${x+7}" cy="${y+2}" r="1.8" fill="#333"/>`;if(kind==='fermata')mark=glyph('\uE4C0',x,y,38);if(kind==='breath')mark=glyph('\uE4CE',x,y,32);if(kind==='legato')mark=`<path d="M ${x} ${y} Q ${x+12} ${y-12} ${x+24} ${y}" fill="none" stroke="#333" stroke-width="1.4"/>`;if(kind==='pizzicato'||kind==='arco')mark=`<text x="${x}" y="${y}" class="expression-label">${kind==='pizzicato'?'pizz.':'arco'}</text>`;return mark?`<g class="articulation-symbol" data-articulation="${kind}">${mark}</g>`:'';}
function drawNote(p,n,mid){const {e,x,y,base,top,annotationY,lyricY}=p;let out=`<g class="note-group ${selectedNotes.has(e.id)?'selected':''}" data-id="${e.id}" data-note-voice="${e.voice}" role="button" aria-label="${escapeXml(n.name)}，${M.fmt(M.ticks(e)/48)} 拍"><title>${escapeXml(n.voiceName+' · '+n.name)} · ${M.fmt(M.ticks(e)/48)} 拍${e.lyric?' · '+escapeXml(e.lyric):''}</title><rect class="note-halo" x="${x-16}" y="${Math.min(y-16,base-(e.pitch-p.bottomPitch)*6-16,top-9)}" width="35" height="${Math.max(base+36-Math.min(y-16,base-(e.pitch-p.bottomPitch)*6-16,top-9),35)}" rx="7"/>`;
  if(e.type==='rest')out+=glyph(String.fromCodePoint(0xE4E3+Math.log2(e.duration)),x-6,e.duration===1?top+12:top+24,48,'music-text note-ink');
  else{if(y>base)for(let ly=base+12;ly<=y+1;ly+=12)out+=line(x-4,ly,x+19,ly,'note-ink');if(y<top)for(let ly=top-12;ly>=y-1;ly-=12)out+=line(x-4,ly,x+19,ly,'note-ink');
    if(e.accidental!==null)out+=glyph({'-2':'\uE264','-1':'\uE260','0':'\uE261','1':'\uE262','2':'\uE263'}[e.accidental],x-20,y,48,'music-text note-ink');out+=glyph(e.duration===1?'\uE0A2':e.duration===2?'\uE0A3':'\uE0A4',x,y,48,'music-text note-ink');
    const down=e.pitch>=mid;if(e.duration!==1){const sx=down?x+.6:x+13.6,sy=y+(down?36:-36);out+=line(sx,y,sx,sy,'note-ink','stroke-width="1.3"');if(e.duration>=8)out+=glyph(String.fromCodePoint(0xE240+2*(Math.log2(e.duration)-3)+(down?1:0)),sx,sy,48,'music-text note-ink');}
    const ay=down?Math.min(y-18,top-13):Math.max(y+20,base+16);if(e.articulation==='staccato')out+=`<circle cx="${x+7}" cy="${ay}" r="2" class="note-ink"/>`;if(e.articulation==='accent')out+=`<path d="M ${x+1} ${ay-4} L ${x+14} ${ay} L ${x+1} ${ay+4}" fill="none" stroke="#333"/>`;if(e.articulation==='tenuto')out+=line(x,ay,x+14,ay,'note-ink','stroke-width="2"');if(e.articulation==='fermata')out+=glyph('\uE4C0',x-3,Math.min(y-29,top-14),42);if(e.articulation==='breath')out+=glyph('\uE4CE',x+22,top-8,35);
    if(e.articulation==='staccatissimo')out+=`<path d="M ${x+3} ${ay-5} L ${x+11} ${ay-5} L ${x+7} ${ay+4} Z" class="note-ink"/>`;
    if(e.articulation==='marcato')out+=`<path d="M ${x+1} ${ay+4} L ${x+7} ${ay-5} L ${x+14} ${ay+4}" fill="none" stroke="#333"/>`;
    if(e.articulation==='portato')out+=line(x,ay-3,x+14,ay-3,'note-ink')+`<circle cx="${x+7}" cy="${ay+3}" r="1.8" class="note-ink"/>`;
    if(e.articulation==='legato')out+=drawArticulationSymbol('legato',x-4,Math.min(y-28,top-18));
    if(['pizzicato','arco'].includes(e.articulation))out+=`<text x="${x+7}" y="${Math.min(y-28,top-18)}" text-anchor="middle" class="expression-label">${e.articulation==='pizzicato'?'pizz.':e.articulation}</text>`;
    if(e.ornament)out+=glyph({trill:'\uE566',mordent:'\uE56D',turn:'\uE567'}[e.ornament],x-3,Math.min(y-48,top-28),35);
  }
  for(let dot=0;dot<M.dots(e);dot++)out+=`<circle class="augmentation-dot note-ink" cx="${x+21+dot*7}" cy="${e.type==='note'&&(y-base)%12===0?y-6:y}" r="1.9"/>`;
  if(e.exactTicks!==null&&e.exactTicks!==undefined)out+=`<text x="${x+7}" y="${Math.max(y+26,base+18)}" text-anchor="middle" font-size="8" fill="#7f887a">${M.fmt(M.ticks(e)/48)}拍</text>`;
  if(e.dynamic)out+=`<text x="${x+7}" y="${annotationY}" text-anchor="middle" class="notation-label">${e.dynamic}</text>`;
  if(e.expression){if(['crescendo','diminuendo'].includes(e.expression)){const wide=e.expression==='crescendo';out+=`<path d="M ${x-12} ${annotationY+(wide?0:-5)} L ${x+25} ${annotationY+(wide?-5:0)} M ${x-12} ${annotationY+(wide?0:5)} L ${x+25} ${annotationY+(wide?5:0)}" stroke="#333" fill="none"/>`;}else out+=`<text x="${x+7}" y="${Math.min(y-57,top-38)}" text-anchor="middle" class="expression-label">${e.expression}</text>`;}
  if(e.lyric&&e.type==='note')out+=`<text x="${x+7}" y="${lyricY}" text-anchor="middle" class="lyrics">${escapeXml(e.lyric)}</text>`;return out+'</g>';
}

function hideMenu(){clearTimeout(hideMenuTimer);hideMenuTimer=null;finishLyricEdit();$('contextMenu').hidden=true;menuTarget=null;}
function cancelHideMenu(){clearTimeout(hideMenuTimer);hideMenuTimer=null;}
function scheduleHideMenu(){if($('contextMenu').hidden||hideMenuTimer!==null)return;hideMenuTimer=setTimeout(()=>{hideMenuTimer=null;if(!$('contextMenu').matches(':hover'))hideMenu();},120);}
function isSelectedTarget(t){return t?.type==='note'?selectedNotes.has(t.id):t?.type==='measure'?!!selectedMeasureVoices.get(score.measures[t.mi]?.id)?.has(t.voice):t?.type==='symbol'?selectedSymbols.has(symbolKey(t)):false;}
function targetAt(element){const sym=element.closest('[data-symbol-kind]');if(sym)return {type:'symbol',kind:sym.dataset.symbolKind,mi:+sym.dataset.symbolMi,id:sym.dataset.symbolId||''};const note=element.closest('[data-id]');if(note){const f=findNote(note.dataset.id);return f?{type:'note',id:f.e.id,mi:f.mi}:null;}const bar=element.closest('.measure-click');return bar?{type:'measure',mi:+bar.dataset.mi,voice:bar.dataset.voice}:null;}
function hoverTargetAt(event){if(mode!=='select'||symbolTool)return null;const t=targetAt(event.target);if(t?.type==='note'){const p=notePositions.get(t.id),point=coordinates(event);if(!p||!point)return null;const rest=p.e.type==='rest',down=p.e.pitch>=p.bottomPitch+4,stem=!rest&&p.e.duration!==1,centerY=rest&&p.e.duration===1?p.top+12:p.y,above=rest?22:stem&&!down?44:14,below=rest?22:stem&&down?44:14;if(point.x<p.x-24||point.x>p.x+32||point.y<centerY-above||point.y>centerY+below)return null;}return t;}
function showMenu(t,x,y){if(mode!=='select'||symbolTool){hideMenu();return;}if(!isSelectedTarget(t)){scheduleHideMenu();return;}cancelHideMenu();const key=t.type==='symbol'?symbolKey(t):t.type+':'+(t.id||t.mi)+':'+(t.voice||''),old=menuTarget;menuTarget=t;menuTarget._key=key;const menu=$('contextMenu');if(menu.hidden||old?._key!==key){buildMenu();menu.hidden=false;const width=menu.offsetWidth,left=x+12+width<=window.innerWidth-8?x+12:x-width-12;menu.style.left=Math.max(8,Math.min(left,window.innerWidth-width-8))+'px';menu.style.top=Math.max(8,Math.min(y+8,window.innerHeight-menu.offsetHeight-84))+'px';}}
function menuChoice(label,attr,value,active=false){return `<button class="menu-choice${active?' active':''}" ${attr}="${escapeXml(JSON.stringify(value))}">${escapeXml(label)}</button>`;}
const propChoice=(k,v,label)=>menuChoice(label,`data-prop="${k}" data-value`,v);
const settingChoice=(k,v,label)=>menuChoice(label,`data-setting="${k}" data-value`,v);
const actionChoice=(action,label)=>`<button class="menu-choice" data-action="${action}">${escapeXml(label)}</button>`;
function category(label,html){return `<div class="menu-category"><button class="menu-category-title" aria-expanded="false">${escapeXml(label)}<span aria-hidden="true">›</span></button><div class="submenu">${html}</div></div>`;}
function buildMenu(){if(!menuTarget||!isSelectedTarget(menuTarget)){hideMenu();return;}const notes=selectedList(),bars=score.measures.filter(m=>selectedMeasures.has(m.id)),f=getSelected(),c=config();let out='';
  if(notes.length)out+=category('升降记号',[[null,'自动／沿用'],[1,'♯ 升'],[-1,'♭ 降'],[0,'♮ 还原'],[2,'𝄪 重升'],[-2,'𝄫 重降']].map(([v,l])=>propChoice('accidental',v,l)).join(''));
  if(notes.length)out+=category('时值',[1,2,4,8,16,32,64,128].map(d=>propChoice('duration',d,`${d} 分音符`)).join('')+'<div class="menu-divider"></div>'+[0,1,2,3].map(d=>propChoice('dots',d,['无附点','附点 ·','复附点 ··','三附点 ···'][d])).join(''));
  if(bars.length){out+=category('调号',(c.mode==='minor'?M.MINOR:M.MAJOR).map((n,i)=>settingChoice('key',i-7,n+(c.mode==='minor'?' 小调':' 大调'))).join(''));out+=category('调式',settingChoice('mode','major','大调')+settingChoice('mode','minor','小调'));out+=category('拍号／节奏',meterValues.map(v=>settingChoice('meter',v.split('/').map(Number),v)).join(''));out+=category('速度',`<label class="menu-field">♩ / 分钟<input id="menuBpm" type="number" min="30" max="240" value="${c.bpm}"></label>`+actionChoice('setBpm','设置速度…'));out+=category('当前声部谱号',Object.entries(clefNames).map(([v,l])=>settingChoice('clef',v,l)).join(''));}
  if(notes.length||bars.length){out+=category('力度',propChoice('dynamic','','取消力度')+dynamics.map(v=>propChoice('dynamic',v,v)).join(''));out+=category('表情',propChoice('expression','','取消表情')+M.EXPRESSIONS.map(([v,l])=>propChoice('expression',v,`${v} · ${l}`)).join(''));out+=category('奏法',propChoice('articulation','','取消奏法')+articulations.map(([v,l])=>propChoice('articulation',v,l)).join(''));out+=category('装饰音',propChoice('ornament','','取消装饰音')+[['trill','tr · 颤音'],['mordent','波音'],['turn','回音']].map(([v,l])=>propChoice('ornament',v,l)).join(''));out+=category('八度线',[[0,'取消八度线'],[1,'8va · 高八度'],[-1,'8vb · 低八度'],[2,'15ma · 高两八度'],[-2,'15mb · 低两八度']].map(([v,l])=>menuChoice(l,'data-menu-symbol="ottava" data-value',v)).join(''));}
  if(notes.length){out+=category('连线',menuChoice('添加延音线','data-menu-symbol="tie" data-value',true)+propChoice('tie',false,'取消延音线')+menuChoice('添加圆滑线','data-menu-symbol="slur" data-value','add')+actionChoice('removeSlur','取消圆滑线'));out+=category('音高',actionChoice('pitchUp','↑ 上移一个谱位')+actionChoice('pitchDown','↓ 下移一个谱位'));const lyric=notes.find(e=>e.id===selected&&e.type==='note')||notes.find(e=>e.type==='note');if(lyric)out+=category('歌词',`<label class="menu-field">歌词<input id="menuLyric" data-lyric-id="${lyric.id}" value="${escapeXml(lyric.lyric)}" maxlength="80" placeholder="输入歌词，Enter 保存"></label>`+actionChoice('saveLyric','保存歌词'));}
  if(bars.length)out+=category('反复／返回',menuChoice('𝄆 反复起点','data-menu-symbol="repeatStart" data-value',true)+menuChoice('取消反复起点','data-menu-symbol="repeatStart" data-value',false)+[0,2,3,4,5,6,7,8].map(v=>menuChoice(v?`𝄇 共 ${v} 遍`:'取消反复终点','data-menu-symbol="repeatEnd" data-value',v)).join('')+['','1','2','3','1,2','2,3'].map(v=>menuChoice(v?`${v}. 结尾`:'取消结尾','data-menu-symbol="ending" data-value',v)).join('')+Object.entries(navNames).map(([v,l])=>menuChoice(l,'data-menu-symbol="navigation" data-value',v)).join('')+menuChoice('取消返回标记','data-menu-symbol="navigation" data-value',''));
  if(selectedSymbols.size){const t=[...selectedSymbols.values()].at(-1);let html='';if(t.kind==='ottava'||t.kind==='measureOctave')html=[[0,'取消八度线'],[1,'8va'],[-1,'8vb'],[2,'15ma'],[-2,'15mb']].map(([v,l])=>menuChoice(l,'data-symbol-value',v)).join('');else if(t.kind==='repeatEnd')html=[2,3,4,5,6,7,8].map(v=>menuChoice(`共 ${v} 遍`,'data-symbol-value',v)).join('');else if(t.kind==='ending')html=['1','2','3','1,2','2,3'].map(v=>menuChoice(`${v}. 结尾`,'data-symbol-value',v)).join('');else if(t.kind==='navigation')html=Object.entries(navNames).map(([v,l])=>menuChoice(l,'data-symbol-value',v)).join('');else if(t.kind==='tuplet'){const e=findNote(t.id)?.e;html=`<label class="menu-field">连音数量<input id="menuTupletCount" type="number" min="2" max="32" value="${e?.tuplet?.count||3}"></label><label class="menu-field">总时值（四分拍）<input id="menuTupletTotal" type="number" min="0.125" max="32" step="0.125" value="${e?.tuplet?.total||1}"></label>`+actionChoice('updateTuplet','修改连音组');}out+=category('所选符号',html+actionChoice('removeSymbols','删除所选符号'));}
  out+=category('删除',actionChoice('delete','删除所选对象'));$('contextMenu').innerHTML=out;
}
function openCategory(cat){const menu=$('contextMenu');menu.querySelectorAll('.menu-category').forEach(e=>{e.classList.toggle('open',e===cat);e.querySelector('.menu-category-title').setAttribute('aria-expanded',String(e===cat));});const sub=cat.querySelector('.submenu'),r=cat.getBoundingClientRect(),mr=menu.getBoundingClientRect();sub.style.left=Math.max(8,Math.min(mr.right-1,window.innerWidth-sub.offsetWidth-8))+'px';sub.style.top=Math.max(8,Math.min(r.top,window.innerHeight-sub.offsetHeight-82))+'px';}
$('contextMenu').addEventListener('pointerover',e=>{cancelHideMenu();const cat=e.target.closest('.menu-category');if(cat&&!cat.classList.contains('open'))openCategory(cat);});$('contextMenu').addEventListener('pointerleave',scheduleHideMenu);
document.addEventListener('pointerover',e=>{if(!$('score').contains(e.target)&&!$('contextMenu').contains(e.target))hideMenu();});window.addEventListener('blur',hideMenu);
function setAnnotation(k,v){if(['dynamic','expression','articulation','ornament'].includes(k)){commit(()=>{selectedList().forEach(e=>e[k]=v);score.measures.filter(m=>selectedMeasures.has(m.id)).forEach(m=>m[k]=v);});defaults[k]=v;}else setProp(k,v);}
function saveLyric(){const input=$('menuLyric');if(!input)return;const f=findNote(input.dataset.lyricId),value=input.value;if(f)commit(()=>f.e.lyric=value);}
function finishLyricEdit(){if(lyricEditBefore!==null&&lyricEditBefore!==snapshot()){undoStack.push(lyricEditBefore);if(undoStack.length>120)undoStack.shift();redoStack=[];}lyricEditBefore=null;}
$('contextMenu').addEventListener('focusin',e=>{if(e.target.id==='menuLyric')lyricEditBefore=snapshot();});
$('contextMenu').addEventListener('input',e=>{if(e.target.id!=='menuLyric')return;const f=findNote(e.target.dataset.lyricId);if(f){f.e.lyric=e.target.value;renderScore();save();}});
$('contextMenu').addEventListener('focusout',e=>{if(e.target.id==='menuLyric'){finishLyricEdit();syncTools();}});
$('contextMenu').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.classList.contains('menu-category-title')){openCategory(b.parentElement);return;}if(b.dataset.setting){requestSetting(b.dataset.setting,JSON.parse(b.dataset.value));return;}if(b.dataset.prop){setAnnotation(b.dataset.prop,JSON.parse(b.dataset.value));return;}if(b.dataset.menuSymbol){useSymbol(b.dataset.menuSymbol,JSON.parse(b.dataset.value),b.textContent);return;}if(b.hasAttribute('data-symbol-value')){editSymbols(JSON.parse(b.dataset.symbolValue));return;}const action=b.dataset.action;if(action==='delete')deleteSelected();if(action==='pitchUp')movePitch(1);if(action==='pitchDown')movePitch(-1);if(action==='setBpm')requestSetting('bpm',Number($('menuBpm').value));if(action==='saveLyric')saveLyric();if(action==='removeSlur')commit(()=>{const ids=new Set(selectedList().map(e=>e.slur).filter(Boolean));score.measures.flatMap(m=>m.events).filter(e=>ids.has(e.slur)).forEach(e=>e.slur='');});if(action==='removeSymbols')commit(()=>{selectedSymbols.forEach(removeSymbol);selectedSymbols.clear();hideMenu();});if(action==='updateTuplet')updateTupletSymbols();});
$('contextMenu').addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='menuLyric'){e.preventDefault();saveLyric();}});
$('contextMenu').addEventListener('change',e=>{if(e.target.id==='menuLyric')saveLyric();});
function requestSetting(k,value){if(k==='bpm'&&(!Number.isFinite(value)||value<30||value>240)){toast('速度应在 30–240 之间。');syncSettings();return;}hideMenu();const chosen=score.measures.map((m,i)=>selectedMeasures.has(m.id)?i:-1).filter(i=>i>=0),indices=chosen.length?chosen:[currentMeasure],start=Math.min(...indices);pendingScope={k,value,indices,start,voice:activeVoice};$('scopeDescription').textContent=`${{key:'调号',mode:'调式',meter:'拍号',bpm:'速度',clef:'谱号'}[k]}修改 · 第 ${start+1} 小节${indices.length>1?'；“当前小节”会修改全部选中的小节':''}`;$('scopeDialog').showModal();}
function applyScope(following){const p=pendingScope;pendingScope=null;$('scopeDialog').close();if(!p)return;commit(()=>{const indices=following?score.measures.map((m,i)=>i).filter(i=>i>=p.start):p.indices;indices.forEach(mi=>{const m=score.measures[mi];if(p.k==='clef'){m.clefs??={};m.clefs[p.voice]=p.value;}else m[p.k]=Array.isArray(p.value)?[...p.value]:p.value;});});}
$('scopeCurrent').onclick=()=>applyScope(false);$('scopeFollowing').onclick=()=>applyScope(true);$('cancelScope').onclick=()=>{pendingScope=null;$('scopeDialog').close();syncSettings();};$('scopeDialog').addEventListener('cancel',()=>{pendingScope=null;syncSettings();});

function coordinates(event){const svg=$('score').querySelector('svg');if(!svg)return null;const p=svg.createSVGPoint();p.x=event.clientX;p.y=event.clientY;return p.matrixTransform(svg.getScreenCTM().inverse());}
function clearPlaceholders(mi,voice){score.measures[mi].events=score.measures[mi].events.filter(e=>!(e.voice===voice&&e.placeholder));}
