$('score').addEventListener('pointermove',e=>{const t=targetAt(e.target),hover=hoverTargetAt(e);if(isSelectedTarget(hover))showMenu(hover,e.clientX,e.clientY);else scheduleHideMenu();const p=coordinates(e),ghost=$('ghost');if(!p||!ghost)return;const g=geometry.find(g=>p.x>=g.start&&p.x<g.end&&p.y>=g.offset+4&&p.y<g.rowEnd-4);if(!g||mode!=='edit'||symbolTool||t?.type!=='measure'){ghost.innerHTML='';return;}const pitch=Math.max(0,Math.min(66,g.bottomPitch+Math.round((g.base-p.y)/6))),y=g.base-(pitch-g.bottomPitch)*6;ghost.innerHTML=glyph('\uE0A4',p.x,y)+`<text x="${p.x+20}" y="${y-8}" font-size="10" fill="#38624f">${M.pitchName(pitch,M.keyMap(config(g.mi,g.voice).key)[M.letter(pitch)]||0)}</text>`;});$('score').addEventListener('pointerleave',()=>{if($('ghost'))$('ghost').innerHTML='';scheduleHideMenu();});
