    const audible=score.voices.filter(v=>!v.muted&&(!$('solo').checked||v.id===activeVoice)).map(v=>v.id),samples=new Map();await Promise.all(t.notes.filter(n=>n.midi!==null&&audible.includes(n.voice)).map(async n=>{if(!samples.has(n.midi))samples.set(n.midi,pianoBuffer(n.midi));}));await Promise.all(samples.values());if(session.cancelled)return;
